


export type CreateSubscriptionOfferRequest = { /** minItems: 1. maxItems: 12. */ "billing_interval_options": Array<{ "billing_interval": "daily" | "weekly" | "monthly" | "yearly" | (string & {}); /** Format: int32. minimum: 1. maximum: 365. */ "billing_interval_count": number; }>; "metadata"?: Record<string, string>; /** minLength: 1. maxLength: 255. */ "name": string; /** Catalog targets for new signups. At least one product or variant is required. maxItems: 100. */ "product_ids"?: Array<string>; /** An active promotion with forever recurrence. On PATCH, null removes the discount for new signups; omission keeps it. */ "promotion_id"?: string | null; "status"?: "active" | "inactive" | (string & {}); /** Delivery methods offered at signup. An empty array uses the store's checkout defaults. Existing subscriptions keep their selected method. maxItems: 25. */ "subscription_delivery_method_ids"?: Array<string>; /** Catalog targets for new signups. At least one product or variant is required. maxItems: 100. */ "variant_ids"?: Array<string>; };
